 * Quiz component logic.
 * Mirrors a React-style component structure: declarative data → render → event handling.
 */

// ── Quiz data ─────────────────────────────────────────────────────────────────

const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1 of 3",
    text: "Which of the following are statically typed languages?",
    helpText: "Select all that apply. Statically typed languages check types at compile time rather than at runtime.",
    options: [
      { value: "java",       label: "Java" },
      { value: "python",     label: "Python" },
      { value: "cpp",        label: "C++" },
      { value: "javascript", label: "JavaScript" },
    ],
    correct: new Set(["java", "cpp"]),
  },
  {
    id: "q2",
    number: "Question 2 of 3",
    text: "Which languages include automatic garbage collection?",
    helpText: null,
    options: [
      { value: "c",      label: "C" },
      { value: "java",   label: "Java" },
      { value: "python", label: "Python" },
      { value: "rust",   label: "Rust" },
    ],
    correct: new Set(["java", "python"]),
  },
  {
    id: "q3",
    number: "Question 3 of 3",
    text: "Which of the following are traditionally compiled (ahead-of-time) languages?",
    helpText: null,
    options: [
      { value: "python",     label: "Python" },
      { value: "c",          label: "C" },
      { value: "javascript", label: "JavaScript" },
      { value: "go",         label: "Go" },
    ],
    correct: new Set(["c", "go"]),
  },
];

// ── Render ────────────────────────────────────────────────────────────────────

function renderQuiz() {
  const form = document.getElementById("quiz-form");

  QUESTIONS.forEach((q) => {
    const field = document.createElement("div");
    field.className = "form-field";
    field.id = `field-${q.id}`;

    const errorId = `error-${q.id}`;

    field.innerHTML = `
      <fieldset aria-describedby="${q.helpText ? `help-${q.id} ` : ""}${errorId}">
        <legend>
          <span class="question-number" aria-hidden="true">${q.number}</span>
          ${escapeHtml(q.text)}
        </legend>
        ${q.helpText ? `<span id="help-${q.id}" class="help-text">${escapeHtml(q.helpText)}</span>` : ""}
        <ul class="options-list" role="list">
          ${q.options
            .map(
              (opt) => `
            <li class="option-item">
              <label>
                <input
                  type="checkbox"
                  name="${q.id}"
                  value="${escapeHtml(opt.value)}"
                  aria-describedby="${errorId}"
                />
                <span class="option-text">${escapeHtml(opt.label)}</span>
              </label>
            </li>`
            )
            .join("")}
        </ul>
        <span id="${errorId}" class="field-error" role="alert" aria-live="polite">
          Please select at least one answer.
        </span>
      </fieldset>
    `;

    form.insertBefore(field, document.getElementById("submit-row"));
  });
}

// ── Event handling ────────────────────────────────────────────────────────────

function handleSubmit(event) {
  event.preventDefault();

  let firstInvalid = null;
  let totalCorrect = 0;

  QUESTIONS.forEach((q) => {
    const field = document.getElementById(`field-${q.id}`);
    const checked = [...field.querySelectorAll(`input[name="${q.id}"]:checked`)].map(
      (el) => el.value
    );

    // Validation: at least one option selected
    if (checked.length === 0) {
      field.classList.add("invalid");
      if (!firstInvalid) firstInvalid = field.querySelector("input");
    } else {
      field.classList.remove("invalid");

      // Scoring: exact match required
      const isCorrect =
        checked.length === q.correct.size && checked.every((v) => q.correct.has(v));
      if (isCorrect) totalCorrect++;
    }
  });

  if (firstInvalid) {
    firstInvalid.focus();
    return;
  }

  showResult(totalCorrect);
}

function showResult(score) {
  const banner = document.getElementById("result-banner");
  const total = QUESTIONS.length;

  banner.className = "show";

  if (score === total) {
    banner.classList.add("success");
    banner.textContent = `🎉 Perfect score! You got all ${total} questions correct.`;
  } else if (score >= Math.ceil(total / 2)) {
    banner.classList.add("partial");
    banner.textContent = `✅ Good effort — ${score} out of ${total} correct. Review the ones you missed!`;
  } else {
    banner.classList.add("poor");
    banner.textContent = `❌ You got ${score} out of ${total} correct. Keep studying — you'll get there!`;
  }

  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
  banner.focus();
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// ── Clear invalid state on change ─────────────────────────────────────────────

function clearInvalidOnChange(event) {
  if (event.target.type !== "checkbox") return;
  const fieldId = `field-${event.target.name}`;
  const field = document.getElementById(fieldId);
  if (field && field.classList.contains("invalid")) {
    const anyChecked = field.querySelector(`input[name="${event.target.name}"]:checked`);
    if (anyChecked) field.classList.remove("invalid");
  }
}

// ── Bootstrap ─────────────────────────────────────────────────────────────────

document.addEventListener("DOMContentLoaded", () => {
  renderQuiz();
  document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
  document.getElementById("quiz-form").addEventListener("change", clearInvalidOnChange);
});
