// ── Quiz data ─────────────────────────────────────────────────────────────────

const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1 of 3",
    text: "Which of the following are statically typed languages?",
    helpText: "Select all that apply. Statically typed languages check types at compile time rather than at runtime.",
    options: [
      { value: "java",       label: "Java" },
      { value: "python",     label: "Python" },
      { value: "cpp",        label: "C++" },
      { value: "javascript", label: "JavaScript" },
    ],
    correct: new Set(["java", "cpp"]),
  },
  {
    id: "q2",
    number: "Question 2 of 3",
    text: "Which languages include automatic garbage collection?",
    helpText: null,
    options: [
      { value: "c",      label: "C" },
      { value: "java",   label: "Java" },
      { value: "python", label: "Python" },
      { value: "rust",   label: "Rust" },
    ],
    correct: new Set(["java", "python"]),
  },
  {
    id: "q3",
    number: "Question 3 of 3",
    text: "Which of the following are traditionally compiled (ahead-of-time) languages?",
    helpText: null,
    options: [
      { value: "python",     label: "Python" },
      { value: "c",          label: "C" },
      { value: "javascript", label: "JavaScript" },
      { value: "go",         label: "Go" },
    ],
    correct: new Set(["c", "go"]),
  },
];

// ── Render ────────────────────────────────────────────────────────────────────

function renderQuiz() {
  const form = document.getElementById("quiz-form");

  QUESTIONS.forEach((q) => {
    const field = document.createElement("div");
    field.className = "form-field";
    field.id = `field-${q.id}`;

    const errorId = `error-${q.id}`;

    field.innerHTML = `
      <fieldset aria-describedby="${q.helpText ? `help-${q.id} ` : ""}${errorId}">
        <legend>
          <span class="question-number" aria-hidden="true">${q.number}</span>
          ${escapeHtml(q.text)}
        </legend>
        ${q.helpText ? `<span id="help-${q.id}" class="help-text">${escapeHtml(q.helpText)}</span>` : ""}
        <ul class="options-list" role="list">
          ${q.options
            .map(
              (opt) => `
            <li class="option-item">
              <label>
                <input
                  type="checkbox"
                  name="${q.id}"
                  value="${escapeHtml(opt.value)}"
                  aria-describedby="${errorId}"
