function handleSubmit(event) {
  event.preventDefault();

  let firstInvalid = null;
  let totalCorrect = 0;

  QUESTIONS.forEach((q) => {
    const field = document.getElementById(`field-${q.id}`);
    const checked = [...field.querySelectorAll(`input[name="${q.id}"]:checked`)].map(
      (el) => el.value
