    // Validation: at least one option selected
    if (checked.length === 0) {
      field.classList.add("invalid");
      if (!firstInvalid) firstInvalid = field.querySelector("input");
    } else {
      field.classList.remove("invalid");

      // Scoring: exact match required
      const isCorrect =
