      if (isCorrect) totalCorrect++;
    }
  });

  if (firstInvalid) {
    firstInvalid.focus();
    return;
  }

  showResult(totalCorrect);
}

function showResult(score) {
  const banner = document.getElementById("result-banner");
  const total = QUESTIONS.length;

  banner.className = "show";

